# Try a theory: horizontal fill first, then vertical fill
def get_horizontal_test(grid):
    """Check which rows have horizontal patterns"""
    horizontal = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                # Look for horizontal neighbors
                has_left = c > 0 and grid[r][c-1] == grid[r][c]
                has_right = c < len(grid[0])-1 and grid[r][c+1] == grid[r][c]
                if has_left or has_right:
                    # This row has a horizontal component
                    horizontal.add(r)
    return horizontal

def get_vertical_test(grid):
    """Check which cols have vertical patterns"""
    vertical = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                # Look for vertical neighbors
                has_above = r > 0 and grid[r-1][c] == grid[r][c]
                has_below = r < len(grid)-1 and grid[r+1][c] == grid[r][c]
                if has_above or has_below:
                    vertical.add(c)
    return vertical

# Apply the rule: horizontal-rows get full row filled, vertical-cols get full col filled
def apply_simple_rule(grid):
    h_rows = get_horizontal_test(grid)
    v_cols = get_vertical_test(grid)

    result = [row[:] for row in grid]

    for r in h_rows:
        row_color = grid[r][0]  # Get the color from first non-zero
        # Find the actual pattern color
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                row_color = grid[r][c]
                break
        for c in range(len(grid[0])):
            result[r][c] = row_color

    for c in v_cols:
        col_color = grid[0][c] if grid[0][c] != 0 else None
        for r in range(len(grid)):
            if any(grid[r][c] != 0 for r in range(len(grid))):
                col_color = grid[r][c]
                break
        if col_color:
            for r in range(len(grid)):
                result[r][c] = col_color

    return result

